          <li>
            {{ g.grade }}: <strong [attr.data-testid]="'grade-ledger-' + g.grade">{{ g.total }}</strong>
          </li>
        }
      </ul>
    </section>
    <section aria-labelledby="grade-apex-heading">
      <h2 id="grade-apex-heading">Top per grade</h2>
      <ul>
        @for (g of gradeApexes(); track g.grade) {
