  protected readonly tierLedger = computed(() =>
    TIERS.map((tier) => ({
      tier,
      total: this.people()
        .filter((p) => p.tier === tier)
        .reduce((total, p) => total + (p.momentum ?? 0), 0),
    })),
  );
  protected readonly gradeTally = computed(() =>
    [...GRADES].reverse().map((grade) => ({
      grade,
      count: this.people().filter((p) => p.grade !== null && TALLIED_GRADE[p.grade] === grade).length,
    })),
  );
  protected readonly gradeShare = computed(() => {
    const headcount = this.headcount();
    return GRADES.map((grade) => ({
      grade,
      percent:
        headcount === 0
          ? null
          : Math.floor((this.people().filter((p) => p.grade === grade).length * 100) / headcount),
    }));
  });
  protected readonly gradeLedger = computed(() =>
    GRADES.map((grade) => ({
      grade,
      total: this.people()
        .filter((p) => p.grade === grade)
        .reduce((total, p) => total + (p.scaled ?? 0), 0),
    })),
  );
  protected readonly gradeApexes = computed(() =>
    GRADES.map((grade) => {
      let apex: { name: string; scaled: number } | null = null;
      for (const p of this.people()) {
        if (p.grade !== grade || p.scaled === null) continue;
        if (!apex || p.scaled > apex.scaled || (p.scaled === apex.scaled && p.name.localeCompare(apex.name) < 0)) {
          apex = { name: p.name, scaled: p.scaled };
        }
      }
      return { grade, name: apex?.name ?? null };
    }),
  );
  protected readonly stateTally = computed(() =>
    STATES.map((state) => ({ state, count: this.people().filter((p) => p.state === state).length })),
  );
  protected readonly stratumCounts = computed(() =>
    STRATA.map((stratum) => ({ stratum, count: this.people().filter((p) => p.stratum === stratum).length })),
  );
